'use client';

import React, { useEffect, useState, useRef } from 'react';

export default function ScreenLoader() {
  const [percent, setPercent] = useState('000%');
  const [isFading, setIsFading] = useState(false);
  const [isDestroyed, setIsDestroyed] = useState(false);
  const animationFrameRef = useRef<number | null>(null);

  useEffect(() => {
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    // Cubic easing function matching user specification
    const ease = (t: number) =>
      t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

    const startTime = performance.now();
    const TOTAL_ANIMATION_DURATION = 4000; // Exactly 4.0s full cycle
    const COUNTER_FILL_DURATION = 2400; // Counter reaches 100% at 2.4s (synchronized with CSS 60%)

    const animate = (currentTime: number) => {
      const elapsed = currentTime - startTime;

      // 1. Calculate counter percentage up to 100%
      const countProgress = Math.min(elapsed / COUNTER_FILL_DURATION, 1);
      const easedProgress = ease(countProgress);
      const currentPercent = Math.round(easedProgress * 100);
      setPercent(String(currentPercent).padStart(3, '0') + '%');

      // 2. Keep the animation running until the full 4.0s sequence completely displays
      if (elapsed < TOTAL_ANIMATION_DURATION) {
        animationFrameRef.current = requestAnimationFrame(animate);
      } else {
        // Animation has completed displaying in full. Gracefully fade out to reveal the site.
        setIsFading(true);
        document.body.style.overflow = originalOverflow;
        setTimeout(() => {
          setIsDestroyed(true);
        }, 650);
      }
    };

    animationFrameRef.current = requestAnimationFrame(animate);

    // Fallback timer: guarantee dismissal after 5.5s under all circumstances
    const safetyTimeout = setTimeout(() => {
      setIsFading(true);
      document.body.style.overflow = originalOverflow;
      setTimeout(() => setIsDestroyed(true), 650);
    }, 5500);

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      clearTimeout(safetyTimeout);
      document.body.style.overflow = originalOverflow;
    };
  }, []);

  if (isDestroyed) {
    return null;
  }

  return (
    <aside
      aria-hidden={isFading}
      aria-label="RexonSoftTech loading screen"
      className={`fixed inset-0 z-[999999] flex flex-col items-center justify-center select-none transition-opacity duration-500 ease-out ${
        isFading ? 'opacity-0 pointer-events-none' : 'opacity-100 pointer-events-auto'
      }`}
      style={{
        background: 'radial-gradient(circle at 50% 45%, #FFFFFF 0%, #FFF3E6 70%, #F5E5D3 100%)',
        paddingTop: 'env(safe-area-inset-top, 0px)',
        paddingBottom: 'env(safe-area-inset-bottom, 0px)',
      }}
    >
      <style dangerouslySetInnerHTML={{ __html: `
:root {
  --rst-loader-R: url(data:image/png;base64,);
  --rst-loader-S: url(data:image/png;base64,);
  --rst-loader-T: url(data:image/png;base64,);
  --rst-loader-logo: url(data:image/png;base64,);
  --rst-loader-gold: #c49a4a;
  --rst-loader-ink: #381932;
}

.rst-wrap {
  height: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 16px;
  box-sizing: border-box;
}

.rst-stage {
  position: relative;
  width: clamp(250px, 76vw, 420px);
  max-height: min(64vh, 420px);
  aspect-ratio: 1;
}

.rst-ring {
  position: absolute;
  left: 50%;
  top: 39.5%;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  border: 1.5px dashed rgba(196, 154, 74, 0.6);
}

.rst-r1 {
  width: 62%;
  aspect-ratio: 1;
  animation: rst-spin 7s linear infinite;
}

.rst-r2 {
  width: 74%;
  aspect-ratio: 1;
  border-color: rgba(56, 25, 50, 0.16);
  animation: rst-spin 11s linear infinite reverse;
}

@keyframes rst-spin {
  to {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}

.rst-l {
  position: absolute;
  inset: 0;
  background: var(--rst-loader-logo) center/100% 100% no-repeat;
  mix-blend-mode: multiply;
  filter: brightness(1.05) contrast(1.06);
  opacity: 0;
}

.rst-l-R {
  background-image: var(--rst-loader-R);
  animation: rst-R 4s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}

.rst-l-S {
  background-image: var(--rst-loader-S);
  animation: rst-S 4s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}

.rst-l-T {
  background-image: var(--rst-loader-T);
  animation: rst-T 4s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}

.rst-l-W {
  clip-path: inset(54% 9% 28% 9%);
  animation: rst-W 4s cubic-bezier(0.65, 0, 0.35, 1) forwards;
}

@keyframes rst-R {
  0% {
    opacity: 0;
    transform: translateX(-70px);
  }
  22%, 100% {
    opacity: 1;
    transform: none;
  }
}

@keyframes rst-S {
  0%, 8% {
    opacity: 0;
    transform: translateY(70px) scale(0.8);
  }
  30%, 100% {
    opacity: 1;
    transform: none;
  }
}

@keyframes rst-T {
  0%, 16% {
    opacity: 0;
    transform: translateX(70px);
  }
  38%, 100% {
    opacity: 1;
    transform: none;
  }
}

@keyframes rst-W {
  0%, 36% {
    opacity: 0;
    clip-path: inset(54% 50% 28% 50%);
  }
  58%, 100% {
    opacity: 1;
    clip-path: inset(54% 9% 28% 9%);
  }
}

.rst-beam {
  position: absolute;
  left: 12%;
  right: 12%;
  top: 24%;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--rst-loader-gold), transparent);
  box-shadow: 0 0 14px var(--rst-loader-gold);
  opacity: 0;
  animation: rst-beam 4s cubic-bezier(0.65, 0, 0.35, 1) forwards;
}

@keyframes rst-beam {
  0%, 38% {
    opacity: 0;
    top: 24%;
  }
  42% {
    opacity: 1;
  }
  60% {
    opacity: 1;
    top: 55%;
  }
  64%, 100% {
    opacity: 0;
    top: 55%;
  }
}

.rst-meter {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  font-size: clamp(11px, 2.8vw, 13px);
  color: var(--rst-loader-gold);
  font-variant-numeric: tabular-nums;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  letter-spacing: 0.04em;
}

.rst-track {
  width: clamp(140px, 48vw, 210px);
  height: 3px;
  background: rgba(56, 25, 50, 0.09);
  position: relative;
  overflow: hidden;
  border-radius: 9999px;
}

.rst-track i {
  position: absolute;
  inset: 0;
  transform-origin: left;
  background: linear-gradient(90deg, var(--rst-loader-ink), var(--rst-loader-gold));
  animation: rst-fill 4s cubic-bezier(0.65, 0, 0.35, 1) forwards;
  border-radius: 9999px;
}

@keyframes rst-fill {
  0% {
    transform: scaleX(0);
    opacity: 1;
  }
  60%, 100% {
    transform: scaleX(1);
    opacity: 1;
  }
}

.rst-meter span {
  display: inline-block;
  min-width: 4ch;
  text-align: right;
  font-weight: 600;
  color: #381932;
}

@media (prefers-reduced-motion: reduce) {
  .rst-r1, .rst-r2, .rst-l-R, .rst-l-S, .rst-l-T, .rst-l-W, .rst-beam, .rst-track i {
    animation-duration: 8s !important;
  }
}
` }} />

      <div className="rst-wrap">
        <div className="rst-stage" role="img" aria-label="RexonSoftTech loading">
          <div className="rst-ring rst-r2" />
          <div className="rst-ring rst-r1" />
          <div className="rst-l rst-l-R" />
          <div className="rst-l rst-l-S" />
          <div className="rst-l rst-l-T" />
          <div className="rst-l rst-l-W" />
          <div className="rst-beam" />
        </div>
        <div className="rst-meter">
          <div className="rst-track">
            <i />
          </div>
          <span>{percent}</span>
        </div>
      </div>
    </aside>
  );
}
